//
//  WalletKeyInstaller.swift
//  toluWallet
//
//  One tap that puts a wallet on a tag and proves it:
//
//    1. the key slot must be free, the phone key slot free or already this iPhone's
//    2. the curves, then this iPhone's public key as an authentication object
//    3. an ECKey session opened with this iPhone's key (Face ID was asked before)
//    4. the wallet key written inside it — generated by the tag, or the seed
//       phrase's, sent encrypted — bound to this iPhone's key
//    5. the public key read back in the same session
//
//  A tap that drops leaves nothing that blocks a retry: this iPhone's key in
//  its slot is simply used again, and a key written by an earlier try of
//  the same run is picked up (`resumingKey`).
//

import Foundation

enum WalletKeyInstaller {

    /// - Parameters:
    ///   - importing: the seed phrase's key pair, or `nil` for the tag to make one.
    ///   - resumingKey: an earlier try of this run may already have written
    ///     the key; if the slot is taken, read it instead of refusing.
    ///   - keyWriteStarting: called just before the key is written, so the
    ///     caller knows the slot may be used from then on.
    static func install(on tag: Se05xTag, keyObjectId: [UInt8], phoneKeyObjectId: [UInt8],
                        signer: DeviceKeySigner, importing key: SeedPhraseKey?, resumingKey: Bool,
                        keyWriteStarting: () -> Void) async throws -> InstalledWalletKey {
        let uniqueId = try? await tag.readUniqueId()

        let keyExists = try await tag.objectExists(keyObjectId)
        if keyExists && !resumingKey { throw Se05xError.keySlotInUse }
        let phoneSlot = try await tag.phoneKeySlot(phoneKeyObjectId, publicKey: signer.publicKey)
        if phoneSlot == .taken { throw Se05xError.phoneKeySlotTaken }

        if !keyExists { try await tag.prepareCurve(.secp256k1) }
        if phoneSlot == .free {
            try await tag.prepareCurve(.nistP256)
            try await tag.writePhoneKey(phoneKeyObjectId, publicKey: signer.publicKey)
        }

        try await tag.openECKeySession(authObjectId: phoneKeyObjectId, signer: signer)
        if !keyExists {
            keyWriteStarting()
            try await tag.writeWalletKey(keyObjectId, authObjectId: phoneKeyObjectId, importing: key)
        }

        let point = try await tag.readPublicKeyPoint(objectId: keyObjectId)
        if let key, point != key.publicKeyPoint { throw SeedPhraseError.keyMismatch }
        return InstalledWalletKey(publicKey: point, cardUniqueId: uniqueId)
    }

    /// The read-only tap: a wallet key already on the tag, bound to this
    /// iPhone's key. Nothing is written.
    static func readExisting(on tag: Se05xTag, keyObjectId: [UInt8], phoneKeyObjectId: [UInt8],
                             signer: DeviceKeySigner) async throws -> InstalledWalletKey {
        let uniqueId = try? await tag.readUniqueId()
        try await tag.openECKeySession(authObjectId: phoneKeyObjectId, signer: signer)
        let point = try await tag.readPublicKeyPoint(objectId: keyObjectId)
        return InstalledWalletKey(publicKey: point, cardUniqueId: uniqueId)
    }
}
